/**
 * AI SISP Pro - Host Manager
 * Abstraction layer for Office hosts and Standalone mode.
 */

export class HostManager {
    constructor() {
        this.host = "standalone";
        this.officeReady = false;
    }

    async initialize() {
        if (typeof Office !== "undefined") {
            try {
                const info = await Office.onReady();
                if (info.host) {
                    this.host = info.host;
                    this.officeReady = true;
                    console.log(`[HostManager] Office detected: ${this.host}`);
                    return this.host;
                }
            } catch (e) {
                console.warn("[HostManager] Office found but onReady failed:", e);
            }
        }
        console.log("[HostManager] Running in Standalone mode");
        return "standalone";
    }

    isOffice() {
        return this.officeReady;
    }

    async getContextText() {
        if (!this.officeReady) return null;

        try {
            switch (this.host) {
                case Office.HostType.Word:
                    return await this._getWordContext();
                case Office.HostType.Excel:
                    return await this._getExcelContext();
                case Office.HostType.PowerPoint:
                    return await this._getPPTContext();
                default:
                    return null;
            }
        } catch (e) {
            console.error("[HostManager] Error getting context:", e);
            return null;
        }
    }

    async getSelection() {
        if (!this.officeReady) return null;

        try {
            switch (this.host) {
                case Office.HostType.Word:
                    return await this._getWordSelection();
                case Office.HostType.Excel:
                    return await this._getExcelSelection();
                case Office.HostType.PowerPoint:
                    return await this._getPPTSelection();
                default:
                    return null;
            }
        } catch (e) {
            console.error("[HostManager] Error getting selection:", e);
            return null;
        }
    }

    async insertContent(content, location = "end") {
        if (!this.officeReady) {
            navigator.clipboard.writeText(content);
            return "copied";
        }

        try {
            switch (this.host) {
                case Office.HostType.Word:
                    if (location === "replace") return await this._replaceWordSelection(content);
                    if (location === "highlight") return await this._insertWordWithHighlight(content);
                    return await this._insertWord(content);
                case Office.HostType.Excel:
                    return await this._insertExcel(content);
                case Office.HostType.PowerPoint:
                    return await this._insertPPT(content);
            }
        } catch (e) {
            console.error("[HostManager] Error inserting content:", e);
            throw e;
        }
    }

    // --- Word Implementation ---
    async _getWordContext() {
        return await Word.run(async (context) => {
            const selection = context.document.getSelection();
            selection.load("text");
            await context.sync();
            
            if (selection.text.trim()) {
                return selection.text.trim();
            }

            // Fallback to full body if no selection
            const body = context.document.body;
            body.load("text");
            await context.sync();
            return body.text.trim();
        });
    }

    async _getWordSelection() {
        return await Word.run(async (context) => {
            const selection = context.document.getSelection();
            selection.load("text");
            await context.sync();
            return selection.text.trim();
        });
    }

    async _insertWord(content) {
        await Word.run(async (context) => {
            const body = context.document.body;
            body.insertHtml(content, Word.InsertLocation.end);
            await context.sync();
        });
        return "inserted";
    }

    async _replaceWordSelection(content) {
        await Word.run(async (context) => {
            const selection = context.document.getSelection();
            selection.insertHtml(content, Word.InsertLocation.replace);
            await context.sync();
        });
        return "replaced";
    }

    async _insertWordWithHighlight(content) {
        await Word.run(async (context) => {
            const selection = context.document.getSelection();
            const range = selection.insertHtml(content, Word.InsertLocation.replace);
            range.font.highlightColor = "Yellow";
            await context.sync();
        });
        return "highlighted";
    }

    // --- Excel Implementation ---
    async _getExcelContext() {
        return await Excel.run(async (context) => {
            const range = context.workbook.getSelectedRange();
            range.load("values");
            await context.sync();
            
            if (range.values && range.values.some(row => row.some(val => val !== ""))) {
                return range.values.map(row => row.join("\t")).join("\n").trim();
            }

            // Fallback to used range in active worksheet
            const sheet = context.workbook.worksheets.getActiveWorksheet();
            const usedRange = sheet.getUsedRange();
            usedRange.load("values");
            await context.sync();
            return usedRange.values.map(row => row.join("\t")).join("\n").trim();
        });
    }

    async _getExcelSelection() {
        return await Excel.run(async (context) => {
            const range = context.workbook.getSelectedRange();
            range.load("values");
            await context.sync();
            if (range.values && range.values.length > 0) {
                return range.values.map(row => row.join("\t")).join("\n").trim();
            }
            return null;
        });
    }

    async _insertExcel(content) {
        await Excel.run(async (context) => {
            const range = context.workbook.getSelectedRange();
            const targetRange = range.getOffsetRange(0, 1).getCell(0, 0);
            targetRange.values = [[content]];
            await context.sync();
        });
        return "inserted";
    }

    // --- PPT Implementation ---
    async _getPPTContext() {
        // PPT is tricky for full text, start with selection
        return await this._getPPTSelection();
    }

    async _getPPTSelection() {
        return await PowerPoint.run(async (context) => {
            const selection = context.presentation.getSelectedShapes();
            selection.load("items/textFrame/text");
            await context.sync();
            if (selection.items.length > 0) {
                return selection.items[0].textFrame.text.trim();
            }
            return null;
        });
    }

    async _insertPPT(content) {
        await PowerPoint.run(async (context) => {
            const slide = context.presentation.slides.getItemAt(0);
            const textBox = slide.shapes.addTextBox(50, 50, 400, 200);
            textBox.textFrame.text = content;
            await context.sync();
        });
        return "inserted";
    }
}
