/**
 * AI SISP Pro - File Manager
 * Handles PDF extraction and local file processing.
 */

export class FileManager {
    constructor() {
        if (typeof pdfjsLib !== "undefined") {
            pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/pdf.worker.min.js";
        }
    }

    async extractTextFromPDF(file) {
        if (!file || file.type !== "application/pdf") {
            throw new Error("Không phải file PDF.");
        }

        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        let fullText = "";

        for (let i = 1; i <= pdf.numPages; i++) {
            const page = await pdf.getPage(i);
            const textContent = await page.getTextContent();
            const pageText = textContent.items.map(item => item.str).join(" ");
            fullText += `[Trang ${i}]\n${pageText}\n\n`;
        }

        return fullText;
    }

    setupDropZone(element, onFileReady) {
        element.addEventListener("dragover", (e) => {
            e.preventDefault();
            element.style.borderColor = "var(--accent)";
            element.style.background = "var(--accent-glow)";
        });

        element.addEventListener("dragleave", (e) => {
            e.preventDefault();
            element.style.borderColor = "var(--border)";
            element.style.background = "transparent";
        });

        element.addEventListener("drop", async (e) => {
            e.preventDefault();
            element.style.borderColor = "var(--border)";
            element.style.background = "transparent";

            const file = e.dataTransfer.files[0];
            if (file) {
                onFileReady(file);
            }
        });
    }
}
